originalCss:
:root {
    --bg: #07111e;
    --panel: #0d1b2e;
    --panel2: #10233a;
    --line: #1f3454;
    --acc: #7c9eff;
    --text: #e6edf7;
    --dim: #c7d6ec;
    --faint: #9cb0cf;
    --sb: 260px;
}
* {
    box-sizing: border-box;
}
html,
body {
    margin: 0;
    overflow-x: hidden;
}
body {
    background: var(--bg);
    color: var(--text);
    font-family:
        'Noto Sans JP',
        -apple-system,
        'Hiragino Kaku Gothic ProN',
        'Yu Gothic',
        Meiryo,
        sans-serif;
    line-height: 1.85;
    font-size: 15.5px;
}
.sidebar {
    position: fixed;
    left: 0;
    top: 0;
    bottom: 0;
    width: var(--sb);
    background: #091526;
    border-right: 1px solid var(--line);
    overflow-y: auto;
    padding: 18px 0;
    z-index: 20;
}
.side-title {
    font-weight: 800;
    color: #fff;
    padding: 0 18px 12px;
    font-size: 15px;
}
.sidebar ul {
    list-style: none;
    margin: 0;
    padding: 0;
}
.sidebar a {
    display: block;
    padding: 7px 18px;
    color: var(--dim);
    text-decoration: none;
    font-size: 13px;
    line-height: 1.5;
    border-left: 3px solid transparent;
}
.sidebar a:hover {
    background: #0f2038;
}
.sidebar a.active {
    color: #fff;
    border-left-color: var(--acc);
    background: #112642;
}
.nav-toggle {
    display: none;
    position: fixed;
    top: 10px;
    left: 10px;
    z-index: 30;
    background: var(--panel2);
    color: #fff;
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 8px 12px;
    font: inherit;
    font-size: 13px;
}
.main {
    display: block;
    margin-left: var(--sb);
    padding: 36px 44px 60px;
}
.hero {
    position: relative;
    background: linear-gradient(135deg, #0d1b2e, #0a1626);
    border: 1px solid var(--line);
    border-radius: 16px;
    padding: 30px 32px;
    margin-bottom: 34px;
    overflow: hidden;
}
.hero::before {
    content: '';
    position: absolute;
    top: -80px;
    right: -80px;
    width: 300px;
    height: 300px;
    background: radial-gradient(circle, rgba(124, 158, 255, 0.28), transparent 70%);
}
.eyebrow {
    display: inline-block;
    border: 1px solid var(--acc);
    color: var(--acc);
    border-radius: 999px;
    padding: 3px 14px;
    font-size: 12px;
    font-weight: 700;
    margin-bottom: 12px;
}
.hero-title {
    margin: 0 0 6px;
    font-size: 28px;
    font-weight: 800;
    color: #fff;
    line-height: 1.4;
}
.hero-sub {
    margin: 0 0 14px;
    color: var(--dim);
    font-weight: 700;
}
.hero-note {
    border-top: 1px solid var(--line);
    padding-top: 12px;
    color: var(--dim);
    font-size: 14px;
}
.hero-note p {
    margin: 4px 0;
}
h2 {
    font-size: 22px;
    color: #fff;
    margin: 48px 0 14px;
    padding: 10px 0 10px 14px;
    border-left: 4px solid var(--acc);
    background: linear-gradient(90deg, #0f2038, transparent);
    scroll-margin-top: 16px;
}
h3 {
    font-size: 18px;
    color: #cfe0ff;
    margin: 30px 0 10px;
}
h4 {
    font-size: 16px;
    color: var(--acc);
    margin: 24px 0 8px;
}
p,
li {
    color: var(--text);
}
a {
    color: var(--acc);
    word-break: break-all;
}
strong {
    color: #fff;
}
code {
    font-family: 'JetBrains Mono', monospace;
    background: #0f2038;
    border-radius: 4px;
    padding: 1px 6px;
    font-size: 0.9em;
    overflow-wrap: anywhere;
}
.table-scroll {
    overflow-x: auto;
    margin: 14px 0;
    border: 1px solid var(--line);
    border-radius: 10px;
}
table {
    border-collapse: collapse;
    width: 100%;
    font-size: 14px;
}
th {
    background: #112642;
    color: #fff;
    text-align: left;
}
th,
td {
    padding: 9px 13px;
    border-bottom: 1px solid var(--line);
    vertical-align: top;
    line-height: 1.7;
}
tr:last-child td {
    border-bottom: 0;
}
tbody tr:nth-child(even) {
    background: #0a1829;
}
blockquote.callout {
    margin: 16px 0;
    padding: 10px 18px;
    background: #0e2036;
    border: 1px solid var(--line);
    border-left: 4px solid var(--acc);
    border-radius: 10px;
}
blockquote.callout p {
    margin: 6px 0;
    color: var(--dim);
}
.mermaid-diagram {
    display: block;
    overflow-x: auto;
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 18px;
    margin: 16px 0;
}
.mermaid-diagram svg {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: none;
    flex-shrink: 0;
}
.mermaid-diagram foreignObject {
    overflow: visible;
}
.mermaid-diagram foreignObject div,
.mermaid-diagram foreignObject span,
.mermaid-diagram foreignObject p {
    white-space: normal !important;
    color: inherit;
    margin: 0;
}
details {
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 10px;
    margin: 10px 0;
    padding: 10px 16px;
}
summary {
    cursor: pointer;
    color: #fff;
}
details[open] summary {
    margin-bottom: 8px;
}
.page-footer {
    margin-top: 50px;
    padding-top: 16px;
    border-top: 1px solid var(--line);
    color: var(--faint);
    font-size: 12.5px;
}
ul,
ol {
    padding-left: 1.4em;
}
@media (max-width: 900px) {
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.2s;
    }
    .sidebar.open {
        transform: none;
    }
    .nav-toggle {
        display: block;
    }
    .main {
        margin-left: 0;
        padding: 60px 16px 40px;
    }
    .hero {
        padding: 22px 18px;
    }
    .hero-title {
        font-size: 23px;
    }
}
